#include <ext/pb_ds/assoc_container.hpp>
using namespace __gnu_pbds;
typedef tree<pair<int,int>, null_type, less<pair<int,int>>,
             rb_tree_tag, tree_order_statistics_node_update> ordered_set;

// PBDS route: stamp (value, index) pairs so duplicates stay distinct
long long countInversionsPBDS(const vector<int>& a) {
    ordered_set os;
    long long inv = 0;
    for (int i = 0; i < (int)a.size(); ++i) {
        // elements already inserted that are > a[i]
        inv += i - os.order_of_key({a[i], i});
        os.insert({a[i], i});
    }
    return inv;
}

// Merge-sort route: count how many left-half elements outrank each right pick
long long mergeCount(vector<int>& a, vector<int>& buf, int lo, int hi) {
    if (hi - lo < 2) return 0;
    int mid = (lo + hi) / 2;
    long long inv = mergeCount(a, buf, lo, mid) + mergeCount(a, buf, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) buf[k++] = a[i++];
        else { inv += mid - i; buf[k++] = a[j++]; }   // a[i..mid) all beat a[j]
    }
    while (i < mid) buf[k++] = a[i++];
    while (j < hi)  buf[k++] = a[j++];
    copy(buf.begin() + lo, buf.begin() + hi, a.begin() + lo);
    return inv;
}

class RunningMedian {
    multiset<int> lo, hi;    // lo holds the smaller half (max at rbegin)
    // Invariant: lo.size() == hi.size(), or lo.size() == hi.size() + 1
    void rebalance() {
        while (lo.size() > hi.size() + 1) {
            hi.insert(*lo.rbegin());
            lo.erase(prev(lo.end()));
        }
        while (lo.size() < hi.size()) {
            lo.insert(*hi.begin());
            hi.erase(hi.begin());
        }
    }
public:
    void insert(int x) {
        if (lo.empty() || x <= *lo.rbegin()) lo.insert(x);
        else hi.insert(x);
        rebalance();
    }
    void erase(int x) {
        auto it = lo.find(x);
        if (it != lo.end()) lo.erase(it);          // erase(iterator): ONE copy
        else { it = hi.find(x); if (it != hi.end()) hi.erase(it); }
        rebalance();
    }
    double median() const {
        if (lo.empty()) return 0.0;
        if (lo.size() > hi.size()) return *lo.rbegin();
        return ((double)*lo.rbegin() + *hi.begin()) / 2.0;
    }
};

