import heapq


class RunningMedian:
    """Invariant: lo_size == hi_size, or lo_size == hi_size + 1."""

    def __init__(self):
        self.lo = []            # max-heap (negated): smaller half
        self.hi = []            # min-heap: larger half
        self.delayed = {}       # value -> pending deletions
        self.lo_size = self.hi_size = 0

    def _top(self, heap):
        return -heap[0] if heap is self.lo else heap[0]

    def _prune(self, heap):
        while heap:
            v = self._top(heap)
            if self.delayed.get(v, 0):
                self.delayed[v] -= 1
                if not self.delayed[v]:
                    del self.delayed[v]
                heapq.heappop(heap)
            else:
                break

    def _rebalance(self):
        while self.lo_size > self.hi_size + 1:
            self._prune(self.lo)
            heapq.heappush(self.hi, -heapq.heappop(self.lo))
            self.lo_size -= 1; self.hi_size += 1
            self._prune(self.lo)
        while self.lo_size < self.hi_size:
            self._prune(self.hi)
            heapq.heappush(self.lo, -heapq.heappop(self.hi))
            self.hi_size -= 1; self.lo_size += 1
            self._prune(self.hi)

    def insert(self, x: int) -> None:
        self._prune(self.lo)
        if not self.lo or x <= self._top(self.lo):
            heapq.heappush(self.lo, -x); self.lo_size += 1
        else:
            heapq.heappush(self.hi, x); self.hi_size += 1
        self._rebalance()

    def erase(self, x: int) -> None:
        # Decide the side BEFORE marking x deleted. Pruning first with x already
        # in the delayed map would pop x itself, consume its marker, and leave the top
        # pointing at a different value -- decrementing the wrong half.
        self._prune(self.lo); self._prune(self.hi)
        if self.lo and x <= self._top(self.lo):
            self.lo_size -= 1
        else:
            self.hi_size -= 1
        self.delayed[x] = self.delayed.get(x, 0) + 1
        self._prune(self.lo); self._prune(self.hi)
        self._rebalance()

    def median(self) -> float:
        self._prune(self.lo); self._prune(self.hi)
        if self.lo_size == 0:
            return 0.0
        if self.lo_size > self.hi_size:
            return float(self._top(self.lo))
        return (self._top(self.lo) + self._top(self.hi)) / 2.0

