// Answers "how many distinct values in a[l..r]" for many queries, offline.
vector<int> distinctInRanges(const vector<int>& a,
                             const vector<pair<int,int>>& queries) {
    int n = (int)a.size();
    vector<long long> bit(n + 1, 0);
    auto add = [&](int i, int v) { for (++i; i <= n; i += i & -i) bit[i] += v; };
    auto sum = [&](int i) { long long s = 0; for (++i; i > 0; i -= i & -i) s += bit[i]; return s; };

    // group queries by right end so each is answered when the sweep reaches it
    vector<vector<pair<int,int>>> byRight(n);      // right -> (left, queryId)
    for (int q = 0; q < (int)queries.size(); ++q)
        byRight[queries[q].second].push_back({queries[q].first, q});

    vector<int> out(queries.size());
    unordered_map<int,int> lastSeen;               // value -> its last index
    for (int r = 0; r < n; ++r) {
        auto it = lastSeen.find(a[r]);
        if (it != lastSeen.end()) add(it->second, -1);   // unmark the older copy
        add(r, +1);                                      // mark this one
        lastSeen[a[r]] = r;
        for (auto& [l, id] : byRight[r]) out[id] = (int)(sum(r) - sum(l - 1));
    }
    return out;
}

