def distinct_in_ranges(a: list[int], queries: list[tuple]) -> list[int]:
    """Offline: answers 'distinct values in a[l..r]' for many (l, r) queries."""
    n = len(a)
    bit = [0] * (n + 1)

    def add(i, v):
        i += 1
        while i <= n:
            bit[i] += v
            i += i & -i

    def pref(i):                 # sum over [0..i]
        i += 1
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    # group queries by right end so each is answered when the sweep reaches it
    by_right = [[] for _ in range(n)]
    for qid, (l, r) in enumerate(queries):
        by_right[r].append((l, qid))

    out = [0] * len(queries)
    last_seen = {}
    for r in range(n):
        if a[r] in last_seen:
            add(last_seen[a[r]], -1)     # unmark the older copy
        add(r, +1)                       # mark this one
        last_seen[a[r]] = r
        for l, qid in by_right[r]:
            out[qid] = pref(r) - (pref(l - 1) if l > 0 else 0)
    return out

