// std::hash<long long> is the IDENTITY on libstdc++. An attacker who knows
// the bucket count can feed multiples of it and force every key into one chain.
struct SplitMix64Hash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }
    size_t operator()(uint64_t x) const {
        // seed changes every run, so no fixed input can be precomputed against it
        static const uint64_t SEED =
            chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + SEED);
    }
};

unordered_map<long long, int, SplitMix64Hash> safeFreq(const vector<long long>& a) {
    unordered_map<long long, int, SplitMix64Hash> freq;
    freq.reserve(a.size() * 2);      // fewer rehashes, lower load factor
    for (long long x : a) ++freq[x];
    return freq;
}

// Unhackable fallback: no hashing at all, O(n log n) guaranteed.
vector<pair<long long,int>> freqBySorting(vector<long long> a) {
    sort(a.begin(), a.end());
    vector<pair<long long,int>> out;
    for (size_t i = 0; i < a.size(); ) {
        size_t j = i;
        while (j < a.size() && a[j] == a[i]) ++j;
        out.push_back({a[i], (int)(j - i)});
        i = j;
    }
    return out;
}

#include <ext/pb_ds/assoc_container.hpp>
using namespace __gnu_pbds;
typedef tree<pair<int,int>, null_type, less<pair<int,int>>,
             rb_tree_tag, tree_order_statistics_node_update> ordered_set;

// Interleaved insert / erase / kth-smallest. nth_element cannot be used: it
// destroys ordering and would have to re-run from scratch after every update.
struct OrderStatistic {
    ordered_set os;
    int stamp = 0;
    unordered_map<int, vector<int>> stamps;   // value -> live stamps

    void insert(int v)      { os.insert({v, stamp}); stamps[v].push_back(stamp++); }
    void erase(int v) {
        auto& st = stamps[v];
        if (st.empty()) return;
        os.erase({v, st.back()});
        st.pop_back();
    }
    int kth(int k) const {                    // 1-indexed
        return os.find_by_order(k - 1)->first;
    }
};

