class OrderStatistic:
    """Fenwick tree of counts over compressed values, with binary-lifting select.

    Handles interleaved insert / erase / kth-smallest in O(log n) each.
    Values must be known up front so they can be compressed.
    """

    def __init__(self, universe: list[int]):
        self.vals = sorted(set(universe))
        self.rank = {v: i + 1 for i, v in enumerate(self.vals)}   # 1-indexed
        self.n = len(self.vals)
        self.tree = [0] * (self.n + 1)
        self.size = 0
        self.LOG = max(1, self.n.bit_length())

    def _add(self, i: int, delta: int) -> None:
        while i <= self.n:
            self.tree[i] += delta
            i += i & -i

    def insert(self, v: int) -> None:
        self._add(self.rank[v], 1)
        self.size += 1

    def erase(self, v: int) -> None:
        r = self.rank[v]
        if self._count_upto(r) - self._count_upto(r - 1) == 0:
            return                       # not present; nothing to remove
        self._add(r, -1)
        self.size -= 1

    def _count_upto(self, i: int) -> int:
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & -i
        return s

    def kth(self, k: int) -> int:
        """1-indexed kth smallest. Binary lifting: descend the BIT in O(log n)."""
        if k < 1 or k > self.size:
            raise IndexError("k out of range")
        pos, remaining = 0, k
        for pw in range(self.LOG, -1, -1):
            step = 1 << pw
            if pos + step <= self.n and self.tree[pos + step] < remaining:
                pos += step
                remaining -= self.tree[pos]
        return self.vals[pos]           # pos is 0-indexed into vals
